def transform(g):
    a=[row[:] for row in g]
    n=len(a)
    def orbit(r,c):
        seen={(r,c)}; stack=[(r,c)]
        while stack:
            x,y=stack.pop()
            nxt=[(y,x)]
            z=31-x
            if 0<=z<n: nxt.append((z,y))
            for q in nxt:
                if q not in seen: seen.add(q); stack.append(q)
        return seen
    for r in range(n):
        for c in range(n):
            if a[r][c]==6:
                vals=[a[x][y] for x,y in orbit(r,c) if a[x][y]!=6]
                if vals:
                    # symmetries imply all candidates agree
                    assert len(set(vals))==1, (r,c,vals)
                    a[r][c]=vals[0]
    return a
